create or replace function public.censor_review_comment(value text)
returns text language plpgsql immutable set search_path = pg_catalog as $$
declare result text := coalesce(value,''); matched text[]; word text; normalized text;
begin
  for matched in select regexp_matches(result, '(^|[^a-z0-9])([a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[j]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[s5]+[^a-z0-9]*[a@4]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[j]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+|[g9]+[^a-z0-9]*[o0]+[^a-z0-9]*[b8]+[^a-z0-9]*[l]+[^a-z0-9]*[o0]+[^a-z0-9]*[k]+|[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+|[b8]+[^a-z0-9]*[e3]+[^a-z0-9]*[g9]+[^a-z0-9]*[o0]+|[k]+[^a-z0-9]*[o0]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+|[m]+[^a-z0-9]*[e3]+[^a-z0-9]*[m]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[t7]+|[j]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[c]+[^a-z0-9]*[o0]+[^a-z0-9]*[k]+|[j]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[c]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+|[a@4]+[^a-z0-9]*[s5]+[^a-z0-9]*[u]+|[k]+[^a-z0-9]*[a@4]+[^a-z0-9]*[m]+[^a-z0-9]*[p]+[^a-z0-9]*[r]+[^a-z0-9]*[e3]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[b8]+[^a-z0-9]*[i1]+|[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[i1]+|[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[i1]+[^a-z0-9]*[k]+|[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[j]+[^a-z0-9]*[i1]+[^a-z0-9]*[r]+|[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[j]+[^a-z0-9]*[a@4]+[^a-z0-9]*[y]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[c]+[^a-z0-9]*[o0]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[k]+[^a-z0-9]*[e3]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[k]+[^a-z0-9]*[a@4]+[^a-z0-9]*[i1]+|[b8]+[^a-z0-9]*[r]+[^a-z0-9]*[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[s5]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[k]+[^a-z0-9]*[e3]+[^a-z0-9]*[p]+[^a-z0-9]*[a@4]+[^a-z0-9]*[r]+[^a-z0-9]*[a@4]+[^a-z0-9]*[t7]+|[s5]+[^a-z0-9]*[e3]+[^a-z0-9]*[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+|[s5]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+|[p]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[p]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+[^a-z0-9]*[i1]+|[p]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+[^a-z0-9]*[i1]+[^a-z0-9]*[m]+[^a-z0-9]*[a@4]+[^a-z0-9]*[k]+|[p]+[^a-z0-9]*[e3]+[^a-z0-9]*[p]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[b8]+[^a-z0-9]*[o0]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+|[t7]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+|[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[e3]+[^a-z0-9]*[w]+[^a-z0-9]*[e3]+|[k]+[^a-z0-9]*[i1]+[^a-z0-9]*[m]+[^a-z0-9]*[a@4]+[^a-z0-9]*[k]+|[c]+[^a-z0-9]*[o0]+[^a-z0-9]*[k]+|[c]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+|[j]+[^a-z0-9]*[e3]+[^a-z0-9]*[m]+[^a-z0-9]*[b8]+[^a-z0-9]*[u]+[^a-z0-9]*[t7]+|[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[d]+|[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[t7]+|[l]+[^a-z0-9]*[o0]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[e3]+|[p]+[^a-z0-9]*[e3]+[^a-z0-9]*[l]+[^a-z0-9]*[a@4]+[^a-z0-9]*[c]+[^a-z0-9]*[u]+[^a-z0-9]*[r]+|[f]+[^a-z0-9]*[u]+[^a-z0-9]*[c]+[^a-z0-9]*[k]+|[s5]+[^a-z0-9]*[h]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+[^a-z0-9]*[c]+[^a-z0-9]*[h]+|[a@4]+[^a-z0-9]*[s5]+[^a-z0-9]*[s5]+[^a-z0-9]*[h]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+[^a-z0-9]*[e3]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[s5]+[^a-z0-9]*[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[r]+[^a-z0-9]*[d]+)(?=$|[^a-z0-9])', 'gi') loop
    word := matched[2];
    result := replace(result,word,left(word,least(2,length(word)-2)) || '**' || right(word,1));
  end loop;
  normalized := lower(regexp_replace(normalize(result,NFKD), U&'[\0300-\036f\200b-\200d\feff]', '', 'g'));
  if normalized <> result and normalized ~ '(^|[^a-z0-9])([a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[j]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[s5]+[^a-z0-9]*[a@4]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[j]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+|[g9]+[^a-z0-9]*[o0]+[^a-z0-9]*[b8]+[^a-z0-9]*[l]+[^a-z0-9]*[o0]+[^a-z0-9]*[k]+|[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+|[b8]+[^a-z0-9]*[e3]+[^a-z0-9]*[g9]+[^a-z0-9]*[o0]+|[k]+[^a-z0-9]*[o0]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+|[m]+[^a-z0-9]*[e3]+[^a-z0-9]*[m]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[t7]+|[j]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[c]+[^a-z0-9]*[o0]+[^a-z0-9]*[k]+|[j]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[c]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+|[a@4]+[^a-z0-9]*[s5]+[^a-z0-9]*[u]+|[k]+[^a-z0-9]*[a@4]+[^a-z0-9]*[m]+[^a-z0-9]*[p]+[^a-z0-9]*[r]+[^a-z0-9]*[e3]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[b8]+[^a-z0-9]*[i1]+|[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[i1]+|[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[i1]+[^a-z0-9]*[k]+|[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[j]+[^a-z0-9]*[i1]+[^a-z0-9]*[r]+|[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[j]+[^a-z0-9]*[a@4]+[^a-z0-9]*[y]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[c]+[^a-z0-9]*[o0]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[k]+[^a-z0-9]*[e3]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[k]+[^a-z0-9]*[a@4]+[^a-z0-9]*[i1]+|[b8]+[^a-z0-9]*[r]+[^a-z0-9]*[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[s5]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[k]+[^a-z0-9]*[e3]+[^a-z0-9]*[p]+[^a-z0-9]*[a@4]+[^a-z0-9]*[r]+[^a-z0-9]*[a@4]+[^a-z0-9]*[t7]+|[s5]+[^a-z0-9]*[e3]+[^a-z0-9]*[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+|[s5]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[i1]+[^a-z0-9]*[n]+[^a-z0-9]*[g9]+|[p]+[^a-z0-9]*[a@4]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[p]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+[^a-z0-9]*[i1]+|[p]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+[^a-z0-9]*[i1]+[^a-z0-9]*[m]+[^a-z0-9]*[a@4]+[^a-z0-9]*[k]+|[p]+[^a-z0-9]*[e3]+[^a-z0-9]*[p]+[^a-z0-9]*[e3]+[^a-z0-9]*[k]+|[b8]+[^a-z0-9]*[o0]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+|[t7]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+|[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[e3]+[^a-z0-9]*[w]+[^a-z0-9]*[e3]+|[k]+[^a-z0-9]*[i1]+[^a-z0-9]*[m]+[^a-z0-9]*[a@4]+[^a-z0-9]*[k]+|[c]+[^a-z0-9]*[o0]+[^a-z0-9]*[k]+|[c]+[^a-z0-9]*[u]+[^a-z0-9]*[k]+|[j]+[^a-z0-9]*[e3]+[^a-z0-9]*[m]+[^a-z0-9]*[b8]+[^a-z0-9]*[u]+[^a-z0-9]*[t7]+|[n]+[^a-z0-9]*[g9]+[^a-z0-9]*[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[d]+|[e3]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[o0]+[^a-z0-9]*[t7]+|[l]+[^a-z0-9]*[o0]+[^a-z0-9]*[n]+[^a-z0-9]*[t7]+[^a-z0-9]*[e3]+|[p]+[^a-z0-9]*[e3]+[^a-z0-9]*[l]+[^a-z0-9]*[a@4]+[^a-z0-9]*[c]+[^a-z0-9]*[u]+[^a-z0-9]*[r]+|[f]+[^a-z0-9]*[u]+[^a-z0-9]*[c]+[^a-z0-9]*[k]+|[s5]+[^a-z0-9]*[h]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+|[b8]+[^a-z0-9]*[i1]+[^a-z0-9]*[t7]+[^a-z0-9]*[c]+[^a-z0-9]*[h]+|[a@4]+[^a-z0-9]*[s5]+[^a-z0-9]*[s5]+[^a-z0-9]*[h]+[^a-z0-9]*[o0]+[^a-z0-9]*[l]+[^a-z0-9]*[e3]+|[b8]+[^a-z0-9]*[a@4]+[^a-z0-9]*[s5]+[^a-z0-9]*[t7]+[^a-z0-9]*[a@4]+[^a-z0-9]*[r]+[^a-z0-9]*[d]+)(?=$|[^a-z0-9])' then
    return public.censor_review_comment(normalized);
  end if;
  return result;
