create or replace function public.reject_review_profanity()
returns trigger language plpgsql set search_path = pg_catalog as $$
begin
  new.comment := public.censor_review_comment(new.comment);
  return new;
end; $$;
create policy "Customers can delete own low-rated review" on public.reviews
for delete to authenticated using ((select auth.uid())=user_id and rating between 1 and 4);
grant delete on public.reviews to authenticated;